package com.jstyle.testv8.bleimport android.Manifestimport android.annotation.SuppressLintimport android.app.Serviceimport android.bluetooth.BluetoothAdapterimport android.bluetooth.BluetoothDeviceimport android.bluetooth.BluetoothGattimport android.bluetooth.BluetoothGattCallbackimport android.bluetooth.BluetoothGattCharacteristicimport android.bluetooth.BluetoothGattDescriptorimport android.bluetooth.BluetoothManagerimport android.bluetooth.BluetoothProfileimport android.content.Contextimport android.content.Intentimport android.os.Binderimport android.os.Buildimport android.os.Handlerimport android.os.IBinderimport android.os.Looperimport android.text.TextUtilsimport android.util.Logimport androidx.annotation.RequiresPermissionimport com.example.`2208a2`.ble.DevicesStatusimport com.jstyle.testv8.ble.BleManager.Companion.instanceimport io.reactivex.Observableimport io.reactivex.Observerimport io.reactivex.android.schedulers.AndroidSchedulersimport io.reactivex.disposables.Disposableimport java.util.LinkedListimport java.util.Localeimport java.util.Queueimport java.util.UUIDimport java.util.concurrent.TimeUnitclass BleService : Service() {    private var NeedReconnect = false    var fastconnect: Boolean = false //是否连接成功过设备    var firstadddevices: Boolean = false    val connHandler: Handler = Handler(Looper.getMainLooper()) //用于操作连接的Handler，运行在主线程    var hasp: HashMap<BluetoothDevice?, BluetoothGatt?> = HashMap<BluetoothDevice?, BluetoothGatt?>()    private val kBinder: IBinder = LocalBinder()    private val handler = Handler(Looper.getMainLooper())    private var bluetoothManager: BluetoothManager? = null    private var mBluetoothAdapter: BluetoothAdapter? = null    private var mGatt: BluetoothGatt? = null    var isConnected: Boolean = false        private set    override fun onBind(intent: Intent?): IBinder {        initAdapter()        return kBinder    }    override fun onUnbind(intent: Intent?): Boolean {        return super.onUnbind(intent)    }    /**     * 初始化BLE 如果已经连接就不用再次连     *     * @param bleDevice     * @return     */    private var address: String? = null    private var mContext: Context? = null    fun initBluetoothDevice(address: String?, context: Context?) {        if (null != connectAndroid15) {            connectAndroid15 = BleConnectAndroid15(context)        }        //MyLog.i("开始连接");        fastconnect = false        firstadddevices = true        this.address = address        this.mContext = context        if (this.isConnected) return        if (null != mGatt) {            refreshDeviceCache(mGatt!!)            mGatt = null        }        connectedDevice(address, context)    }    private var scanToConnect = true    private var isScaning = false    @SuppressLint("MissingPermission")    fun startScan(enable: Boolean) {        Log.i(TAG, "startScan: " + enable)        if (!mBluetoothAdapter!!.isEnabled()) {            return        }        if (scanToConnect) {            startScanDevice(true)        } else {            initBluetoothDevice(address!!, mContext)        }        scanToConnect = !scanToConnect    }    @SuppressLint("MissingPermission")    private fun startScanDevice(enable: Boolean) {        if (enable) {            Log.e("BleService", "isScaning" + isScaning)            if (!isScaning) {                handler.postDelayed(object : Runnable {                    override fun run() {                        isScaning = false                        //重新扫描连接                        Log.e("BleService", "重新扫描连接")                        /* if(BleManagerConfig.getInstance().isPairDevices(address)){*/                        if (NeedReconnect && DevicesStatus.Disconect == devicesStatus) {                            connectedDevice(address, mContext)                        }                    }                }, 10000)                Log.e("BleService", "开始扫描DI: " + NeedReconnect)                if (NeedReconnect) {                    if (null != instance?.bluetoothAdapter) {                        /*  if(MyApplication.isBefore){*/                        /*  if(BleManagerConfig.getInstance().isPairDevices(address)){*/                        if (instance?.bluetoothAdapter!!.isEnabled()) {                            val device: BluetoothDevice =                                instance?.bluetoothAdapter!!.getRemoteDevice(                                    address!!.uppercase(Locale.getDefault())                                )                            val ispair: Boolean =                                instance?.isPairDevices(device.getAddress()) == true                            if (!ispair && use147) {                                if (devicesStatus == DevicesStatus.InConnecting) {                                    return                                }                                if (instance?.isBleEnable == true) {                                    if (null != connectAndroid15) {                                        connectAndroid15!!.stopScan()                                    }                                }                                if (instance?.bluetoothAdapter?.isDiscovering() ?: true) {                                    instance?.bluetoothAdapter?.cancelDiscovery()                                }                                ConnectByAndroid15(mContext, device)                            } else {                                if (devicesStatus == DevicesStatus.InConnecting) {                                    return                                }                                connectedDevice(address, mContext)                            }                        }                    }                }            }        } else {            Log.e("BleService", " 低版本关闭扫描")            if (instance?.isBleEnable == true) {                if (null != connectAndroid15) {                    connectAndroid15!!.stopScan()                }            }            if (null != instance?.bluetoothAdapter && instance?.bluetoothAdapter?.isEnabled() == true && instance?.bluetoothAdapter?.isDiscovering() == true) {                instance?.bluetoothAdapter?.cancelDiscovery()            }        }        isScaning = enable    }    private fun initAdapter() {        if (bluetoothManager == null) {            bluetoothManager = getSystemService(BLUETOOTH_SERVICE) as BluetoothManager?            if (bluetoothManager == null) {                return            }        }        mBluetoothAdapter = bluetoothManager!!.getAdapter()    }    /**     * 断开连接     */    fun disconnect() {        Log.i(TAG, "disconnect")        NeedReconnect = false        broadcastUpdate(ACTION_GATT_DISCONNECTED)        if (mGatt != null) {            if (isConnected) {                mGatt!!.disconnect()                mGatt!!.close()                mGatt = null            } else {                Log.i(TAG, "close: ")                mGatt!!.close()                mGatt = null            }        }        isConnected = false    }    /**     * 根据设备的Mac地址断开连接     *     * @param address     */    fun disconnect(address: String?) {        val gatts = ArrayList<BluetoothGatt?>()        for (gatt in arrayGatts) {            if (gatt != null && gatt.getDevice().getAddress() == address) {                gatts.add(gatt)                // gatt.disconnect();                gatt.close()                // gatt = null;            }        }        arrayGatts.removeAll(gatts)    }    inner class LocalBinder : Binder() {        val service: BleService            get() = this@BleService    }    private var discoverCount = 0    private val ob = Any()    private val bleGattCallback: BluetoothGattCallback = object : BluetoothGattCallback() {        override fun onConnectionStateChange(gatt: BluetoothGatt?, status: Int, newState: Int) {            var gatt = gatt            use147 = (NeedReconnect && newState == BluetoothProfile.STATE_DISCONNECTED)            if (status == 133 || newState == 0) {                if (mGatt != null) {                    mGatt!!.disconnect()                    mGatt!!.close()                    refreshDeviceCache(mGatt!!)                    mGatt = null                }                if (gatt != null) {                    gatt.disconnect()                    gatt.close()                    refreshDeviceCache(gatt)                    gatt = null                }                if (NeedReconnect) {                    startScanDevice(true)                }                return            }            var action: String? = null            Log.i(TAG, "onConnectionStateChange:  status" + status + " newstate " + newState)            if (newState == BluetoothProfile.STATE_CONNECTED) {                try {                    connHandler.postDelayed(Runnable { gatt!!.discoverServices() }, 600)                } catch (e: Exception) {                    e.printStackTrace()                }            } else if (newState == BluetoothProfile.STATE_DISCONNECTED) {                isConnected = false                Log.i(TAG, "onConnectionStateChange: " + ACTION_GATT_DISCONNECTED)                if (mGatt != null) {                    mGatt!!.close()                    mGatt = null                }                queues.clear()                if (!NeedReconnect) {                    action = ACTION_GATT_DISCONNECTED                    broadcastUpdate(action)                }                if (!NeedReconnect) {                } else {                    if (fastconnect) {                        fastconnect = false                        Log.e(TAG, "发送异常断开")                    }                    if (status == 133) {                        refreshDeviceCache(gatt!!)                    }                    Observable.timer(5000, TimeUnit.MILLISECONDS)                        .observeOn(AndroidSchedulers.mainThread())                        .subscribe(object : Observer<Long?> {                            override fun onSubscribe(d: Disposable) {                                reConnect_dis = d                            }                            override fun onNext(t: Long) {                                TODO("Not yet implemented")                            }                            override fun onError(e: Throwable) {                                TODO("Not yet implemented")                            }                            override fun onComplete() {                                if (null != reConnect_dis && !reConnect_dis!!.isDisposed()) {                                    reConnect_dis!!.dispose()                                    reConnect_dis = null                                }                                Connect15()                            }                        })                }            }        }        /*         * 搜索device中的services (non-Javadoc)         *         * @see         * android.bluetooth.BluetoothGattCallback#onServicesDiscovered(android         * .bluetooth.BluetoothGatt, int)         */        override fun onServicesDiscovered(gatt: BluetoothGatt?, status: Int) {            // if (mGatt == null)            // return;            if (status == BluetoothGatt.GATT_SUCCESS) {                Log.i(TAG, "BluetoothGatt.GATT_SUCCESS")                if (null == mGatt) { //保证只有一个gatt                    mGatt = gatt                    setCharacteristicNotification(true)                    discoverCount = 0                }            } else {                // mGatt = null;                Log.w(                    "servieDiscovered", "onServicesDiscovered received: "                            + status                )            }        }        override fun onMtuChanged(gatt: BluetoothGatt, mtu: Int, status: Int) {            super.onMtuChanged(gatt, mtu, status)            if (BluetoothGatt.GATT_SUCCESS == status) {                setCharacteristicNotification(true)            } else {                gatt.requestMtu(153)            }        }        /*         * 读取特征�?(non-Javadoc)         *         * @see         * android.bluetooth.BluetoothGattCallback#onCharacteristicRead(android         * .bluetooth.BluetoothGatt,         * android.bluetooth.BluetoothGattCharacteristic, int)         */        override fun onCharacteristicRead(            gatt: BluetoothGatt,            characteristic: BluetoothGattCharacteristic,            status: Int        ) {            if (status == BluetoothGatt.GATT_SUCCESS) {                broadcastUpdate(                    ACTION_DATA_AVAILABLE, characteristic, gatt                        .getDevice().getAddress()                )            } else {            }        }        override fun onDescriptorWrite(            gatt: BluetoothGatt?,            descriptor: BluetoothGattDescriptor?, status: Int        ) {            if (status == BluetoothGatt.GATT_SUCCESS) {                nextQueue()                isConnected = true                broadcastUpdate(ACTION_GATT_onDescriptorWrite)            } else {                Log.i(TAG, "onDescriptorWrite: failed")            }        }        /*         * 特征值的变化 (non-Javadoc)         *         * @see         * android.bluetooth.BluetoothGattCallback#onCharacteristicChanged(android         * .bluetooth.BluetoothGatt,         * android.bluetooth.BluetoothGattCharacteristic)         */        override fun onCharacteristicChanged(            gatt: BluetoothGatt,            characteristic: BluetoothGattCharacteristic        ) {            if (mGatt == null) return            Log.i(                TAG,                "onCharacteristicChanged: " + ResolveData.byte2Hex(characteristic.getValue())            )            broadcastUpdate(                ACTION_DATA_AVAILABLE, characteristic, gatt                    .getDevice().getAddress()            )            //	SendData.sendBus(ACTION_DATA_AVAILABLE, characteristic.getValue());        }        override fun onCharacteristicWrite(            gatt: BluetoothGatt?,            characteristic: BluetoothGattCharacteristic?, status: Int        ) {            if (status == BluetoothGatt.GATT_SUCCESS) {                nextQueue()            } else {                //	MyLog.i("status" + status);            }        }    }    @SuppressLint("MissingPermission")    private fun Connect15() {        if (NeedReconnect) {            if (null !=instance?.bluetoothAdapter) {                /*  if(MyApplication.isBefore){*/                /*  if(BleManagerConfig.getInstance().isPairDevices(address)){*/                if (instance?.bluetoothAdapter?.isEnabled() == true) {                    val device: BluetoothDevice? =                        instance?.bluetoothAdapter?.getRemoteDevice(                            address!!.uppercase(Locale.getDefault())                        )                    val ispair: Boolean =                        instance?.isPairDevices(device?.getAddress()) == true                    if (!ispair && use147) {                        if (devicesStatus == DevicesStatus.InConnecting) {                            return                        }                        if (instance?.bluetoothAdapter?.isDiscovering() ?: true) {                            instance?.bluetoothAdapter?.cancelDiscovery()                            if (null != connectAndroid15) {                                connectAndroid15!!.stopScan()                            }                        }                        connHandler.postDelayed(                            Runnable { ConnectByAndroid15(mContext, device) },                            (if (firstadddevices) 30 else 6500).toLong()                        )                        firstadddevices = false                    } else {                        if (devicesStatus == DevicesStatus.InConnecting) {                            return                        }                        connectedDevice(address, mContext)                    }                }            }        }    }    @SuppressLint("MissingPermission")    private fun connectedDevice(address: String?, context: Context?) {        Log.e(TAG, "connectedDevice: " + address)        if (mGatt != null || TextUtils.isEmpty(address) || this.isConnected) {            Log.e(TAG, "mGatt!=NULL return")            return        }        handler.postDelayed(object : Runnable {            override fun run() {                val device =                    mBluetoothAdapter!!.getRemoteDevice(address!!.uppercase(Locale.getDefault()))                try {                    NeedReconnect = true                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {                        if (mBluetoothAdapter!!.isLe2MPhySupported()) {                            device.connectGatt(                                context,                                false,                                bleGattCallback,                                BluetoothDevice.TRANSPORT_LE,                                BluetoothDevice.PHY_LE_2M_MASK                            )                        } else {                            device.connectGatt(                                context,                                false,                                bleGattCallback,                                BluetoothDevice.TRANSPORT_LE,                                BluetoothDevice.PHY_LE_1M_MASK                            )                        }                    } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {                        device.connectGatt(                            context,                            false,                            bleGattCallback,                            BluetoothDevice.TRANSPORT_LE                        )                    } else {                        device.connectGatt(context, false, bleGattCallback)                    }                } catch (ignored: Exception) {                }            }        }, (if (firstadddevices) 150 else 6000).toLong())    }    private fun ConnectByAndroid15(context: Context?, device: BluetoothDevice?) {        /*    if(!Utils.isRunningForeground(context)){            Log.e(TAG, "15 found in background");            Utils.setTopApp(context);        }else{            Log.e(TAG, "15 found in Foreground");        }*/        if (instance?.isBleEnable == true) {            Log.e(TAG, "startDiscovery")            if (null == connectAndroid15) {                connectAndroid15 = BleConnectAndroid15(context)            }            connectAndroid15!!.SetBluetoothDevice(                device,                object : BleConnectAndroid15.OnScanResults {                    @SuppressLint("MissingPermission")                    override fun Success(date: BluetoothDevice?) {                        Log.e(TAG, "15 found")                        try {                            if (instance?.bluetoothAdapter?.isDiscovering() == true && instance?.isBleEnable == true                            ) {                                instance?.bluetoothAdapter?.cancelDiscovery()                                connectAndroid15!!.stopScan()                            }                        } finally {                            if (devicesStatus === DevicesStatus.InConnecting) {                                return                            }                            Log.e(TAG, "15 found BleConting")                            // broadcastUpdate(EventBusCode.BleConting, address); //连接中                            devicesStatus = DevicesStatus.InConnecting                            ConnectMAC(context, date!!)                        }                    }                    @RequiresPermission(Manifest.permission.BLUETOOTH_SCAN)                    override fun Fail() {                        Log.e(TAG, "15 Fail")                        try {                            if (instance?.bluetoothAdapter?.isDiscovering()== true && instance?.isBleEnable == true) {                                instance?.bluetoothAdapter?.cancelDiscovery()                                if (null != connectAndroid15) {                                    connectAndroid15!!.stopScan()                                }                            }                        } finally {                            ConnectByAndroid15(context, device)                        }                    }                })        } else {            Log.e(TAG, "isDiscovering")        }    }    private fun ConnectMAC(context: Context?, device: BluetoothDevice) {        try {            if (instance?.bluetoothAdapter?.isDiscovering() == true) {                instance?.bluetoothAdapter?.cancelDiscovery()            }        } finally {            if (NeedReconnect) {                connHandler.postDelayed(Dorung(context, device), 500)            }        }    }    private fun Dorung(context: Context?, device: BluetoothDevice): Runnable {        val connectRunnable = Runnable {            try {                NeedReconnect = true                Log.e(TAG, "蓝牙设备: 直接中 isConnecting")                try {                    if (instance?.bluetoothAdapter?.isDiscovering()==true) {                        instance?.bluetoothAdapter?.cancelDiscovery()                    }                } finally {                    Log.e(TAG, "蓝牙设备: 直连中 ..." + device.getAddress())                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {                        if (instance?.bluetoothAdapter?.isLe2MPhySupported() == true) {                            device.connectGatt(                                context,                                false,                                bleGattCallback,                                BluetoothDevice.TRANSPORT_LE,                                BluetoothDevice.PHY_LE_2M_MASK                            )                        } else {                            device.connectGatt(                                context,                                false,                                bleGattCallback,                                BluetoothDevice.TRANSPORT_LE,                                BluetoothDevice.PHY_LE_1M_MASK                            )                        }                    } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {                        device.connectGatt(                            context,                            false,                            bleGattCallback,                            BluetoothDevice.TRANSPORT_LE                        )                    } else {                        device.connectGatt(context, false, bleGattCallback)                    }                }            } catch (ignored: java.lang.Exception) {                Log.e(TAG, "connectedDevice：" + ignored.toString())            }        }        return connectRunnable    }    fun refreshDeviceCache(gatt: BluetoothGatt): Boolean {        try {            val localBluetoothGatt = gatt            val localMethod = localBluetoothGatt.javaClass.getMethod(                "refresh", *arrayOfNulls<Class<*>>(0)            )            if (localMethod != null) {                val bool = (localMethod.invoke(                    localBluetoothGatt, *arrayOfNulls<Any>(0)                ) as Boolean)                return bool            }        } catch (localException: Exception) {            Log.e("s", "An exception occured while refreshing device")        }        return false    }    /**     * 广播     *     * @param action     */    private fun broadcastUpdate(action: String?) {        val bleData: BleData = BleData()        bleData.action = action        RxBus.instance.post(bleData)        //Intent intent = new Intent(action);        //sendBroadcast(intent);    }    /**     * 发�?带蓝牙信息的到广�? *     *     * @param action     * @param characteristic     */    private fun broadcastUpdate(        action: String?,        characteristic: BluetoothGattCharacteristic, mac: String?    ) {        //   Intent intent = new Intent(action);        val data = characteristic.getValue()        val bleData: BleData = BleData()        bleData.action = action        bleData.value = data        RxBus.instance.post(bleData)    }    /**     * 读取设备数据     *     * @param     * @param characteristic     */    fun readValue(characteristic: BluetoothGattCharacteristic?) {        if (mGatt == null) return        mGatt!!.readCharacteristic(characteristic)    }    /**     * 写入设备数据     */    fun writeValue(value: ByteArray?) {        if (mGatt == null || value == null) return        val service = mGatt!!.getService(SERVICE_DATA)        if (service == null) return        val characteristic = service.getCharacteristic(DATA_Characteristic)        if (characteristic == null) return        if (value[0] == 0x47.toByte()) {            NeedReconnect = false        }        characteristic.setValue(value)        Log.i(TAG, "writeValue: " + ResolveData.byte2Hex(value));        mGatt!!.writeCharacteristic(characteristic)    }    fun setCharacteristicNotification(enable: Boolean) {        if (mGatt == null) {            Log.i(TAG, "mGatt == null")            return        }        val service = mGatt!!.getService(SERVICE_DATA)        if (service == null) {            Log.e("log", "service=null，所以不能发送使能数据")            return        }        val characteristic = service.getCharacteristic(NOTIY_Characteristic)        if (characteristic == null) {            Log.e("log", "characteristic=null，所以不能发送使能数据")            return        }        mGatt!!.setCharacteristicNotification(characteristic, enable)        try {            Thread.sleep(20)        } catch (e: InterruptedException) {            e.printStackTrace()        }        val descriptor = characteristic.getDescriptor(NOTIY)        if (descriptor == null) {            Log.e("log", "setCharacteristicNotification  descriptor=null，所以不能发送使能数据")            return        }        descriptor.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE)        if (mGatt == null) {            Log.e(                "log",                "luetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE=null，所以不能发送使能数据"            )            return        }        mGatt!!.writeDescriptor(descriptor)    }    override fun onDestroy() {        super.onDestroy()    }    var queues: Queue<ByteArray?> = LinkedList<ByteArray?>()    fun offerValue(value: ByteArray?) {        queues.offer(value)    }    fun nextQueue() {        val requests = queues        val data = if (requests != null) requests.poll() else null        writeValue(data)    }    companion object {        private const val TAG = "BleService"        private val NOTIY: UUID? = UUID.fromString("00002902-0000-1000-8000-00805f9b34fb")        private val SERVICE_DATA: UUID? = UUID.fromString("0000fff0-0000-1000-8000-00805f9b34fb")        private val DATA_Characteristic: UUID? =            UUID.fromString("0000fff6-0000-1000-8000-00805f9b34fb")        private val NOTIY_Characteristic: UUID? =            UUID.fromString("0000fff7-0000-1000-8000-00805f9b34fb")        const val ACTION_GATT_onDescriptorWrite: String =            "com.jstylelife.ble.service.onDescriptorWrite"        const val ACTION_GATT_CONNECTED: String = "com.jstylelife.ble.service.ACTION_GATT_CONNECTED"        const val ACTION_GATT_DISCONNECTED: String =            "com.jstylelife.ble.service.ACTION_GATT_DISCONNECTED"        const val ACTION_DATA_AVAILABLE: String = "com.jstylelife.ble.service.ACTION_DATA_AVAILABLE"        private val arrayGatts = ArrayList<BluetoothGatt?>() // 存放BluetoothGatt的集�?        var startScanDevice_dis: Disposable? = null        var connectAndroid15: BleConnectAndroid15? = null        var use147: Boolean = false        var devicesStatus: DevicesStatus = DevicesStatus.Disconect        val connHandler: Handler = Handler(Looper.getMainLooper()) //用于操作连接的Handler，运行在主线程        var reConnect_dis: Disposable? = null        var inconnectedDevice: Boolean = false        var firstadddevices: Boolean = false    }}